def assign_skills(character, skills_distribution):
    for skill_id, skill_level in skills_distribution.items():
        definition = SKILL_DEFINITIONS.get(skill_id)
        if definition is None:
            continue
        if skill_level > 10:
            skill_level = 10
        character.skill_levels[skill_id] = skill_level




